CREATE TABLE sys_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE coding_repository (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, name VARCHAR(128) NOT NULL, workspace_path VARCHAR(1024) NOT NULL, git_remote_url VARCHAR(1024), index_status VARCHAR(32) NOT NULL DEFAULT 'PENDING', last_index_commit VARCHAR(64), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE coding_task (id BIGINT PRIMARY KEY AUTO_INCREMENT, trace_id VARCHAR(64) NOT NULL UNIQUE, session_id VARCHAR(64) NOT NULL, user_id BIGINT NOT NULL, repository_id BIGINT NOT NULL, user_requirement TEXT NOT NULL, task_status VARCHAR(32) NOT NULL, current_step VARCHAR(128), max_repair_count INT NOT NULL DEFAULT 3, actual_repair_count INT NOT NULL DEFAULT 0, stop_reason VARCHAR(64), start_time DATETIME, end_time DATETIME, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE coding_task_plan (id BIGINT PRIMARY KEY AUTO_INCREMENT, task_id BIGINT NOT NULL, trace_id VARCHAR(64) NOT NULL, plan_json JSON NOT NULL, version INT NOT NULL DEFAULT 1, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE code_index_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, repository_id BIGINT NOT NULL, module_name VARCHAR(255), file_path VARCHAR(1024) NOT NULL, content_hash VARCHAR(64) NOT NULL, language VARCHAR(32) NOT NULL, index_status VARCHAR(32) NOT NULL, indexed_at DATETIME, UNIQUE KEY uk_repo_file (repository_id,file_path));
CREATE TABLE agent_trace_step (id BIGINT PRIMARY KEY AUTO_INCREMENT, trace_id VARCHAR(64) NOT NULL, task_id BIGINT NOT NULL, parent_step_id BIGINT, sequence_number INT NOT NULL, agent_role VARCHAR(32) NOT NULL, step_type VARCHAR(64) NOT NULL, step_name VARCHAR(128) NOT NULL, input_summary TEXT, output_summary TEXT, step_status VARCHAR(32) NOT NULL, error_message TEXT, start_time DATETIME, end_time DATETIME, duration_ms BIGINT, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_trace_step(trace_id, sequence_number));
CREATE TABLE agent_model_trace (id BIGINT PRIMARY KEY AUTO_INCREMENT, trace_id VARCHAR(64) NOT NULL, task_id BIGINT NOT NULL, step_id BIGINT, model_name VARCHAR(128), prompt_summary TEXT, response_summary TEXT, prompt_tokens INT, completion_tokens INT, total_tokens INT, estimated_cost DECIMAL(18,8), retry_count INT NOT NULL DEFAULT 0, duration_ms BIGINT, finish_reason VARCHAR(64), status VARCHAR(32), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE agent_tool_trace (id BIGINT PRIMARY KEY AUTO_INCREMENT, trace_id VARCHAR(64) NOT NULL, task_id BIGINT NOT NULL, step_id BIGINT, tool_name VARCHAR(128) NOT NULL, input_summary TEXT, output_summary TEXT, status VARCHAR(32) NOT NULL, error_message TEXT, duration_ms BIGINT, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE agent_file_change (id BIGINT PRIMARY KEY AUTO_INCREMENT, trace_id VARCHAR(64) NOT NULL, task_id BIGINT NOT NULL, step_id BIGINT, file_path VARCHAR(1024) NOT NULL, operation_type VARCHAR(32) NOT NULL, before_hash VARCHAR(64), after_hash VARCHAR(64), diff_content MEDIUMTEXT, backup_path VARCHAR(1024), rollback_status VARCHAR(32), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE agent_test_trace (id BIGINT PRIMARY KEY AUTO_INCREMENT, trace_id VARCHAR(64) NOT NULL, task_id BIGINT NOT NULL, step_id BIGINT, repair_round INT NOT NULL, command VARCHAR(1024) NOT NULL, exit_code INT, test_status VARCHAR(32) NOT NULL, total_tests INT, passed_tests INT, failed_tests INT, skipped_tests INT, stdout_summary TEXT, stderr_summary TEXT, duration_ms BIGINT, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE agent_repair_trace (id BIGINT PRIMARY KEY AUTO_INCREMENT, trace_id VARCHAR(64) NOT NULL, task_id BIGINT NOT NULL, repair_round INT NOT NULL, error_summary TEXT, repair_plan JSON, result_summary TEXT, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
